UPDATE wallets
SET balance = balance - #{amount},
    frozen_balance = frozen_balance + #{amount},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND currency_id = #{currencyId}
  AND wallet_type = 'SPOT'
  AND balance >= #{amount}

UPDATE wallets
SET balance = balance + #{amount},
    frozen_balance = frozen_balance - #{amount},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND currency_id = #{currencyId}
  AND wallet_type = 'SPOT'
  AND frozen_balance >= #{amount}

UPDATE wallets
SET frozen_balance = frozen_balance - #{amount},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND currency_id = #{currencyId}
  AND wallet_type = 'SPOT'
  AND frozen_balance >= #{amount}

UPDATE wallets
SET balance = balance + #{amount},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND currency_id = #{currencyId}
  AND wallet_type = 'SPOT'
